cd /testbed && python -c "from sympy.sets.tests.test_conditionset import *; import sys
# Run all test functions
import inspect
tests = [(name, obj) for name, obj in inspect.getmembers(sys.modules[__name__]) if name.startswith('test_') and callable(obj)]
for name, func in sorted(tests):
    try:
        func()
        print(f'PASS: {name}')
    except Exception as e:
        print(f'FAIL: {name}: {e}')
"

